     if(b.y+b.h>c.y) bad.push(tg+'the card is not above the key (bottom '+Math.round(b.y+b.h)+', key top '+Math.round(c.y)+')');
     if(b.x>c.x+c.w||b.x+b.w<c.x) bad.push(tg+'the card is not over its key');
