       if(!find(/^DMG$/,c)||!find(/^HANDLING$/,c)) bad.push(tg+'the card over the belt has no stat rows');
       if(!find(/^VS AUTO RIFLE MK III$/,c)) bad.push(tg+'the card does not compare with the gun in hand');
